INSERT INTO `t_case` (`case_id`, `case_name`, `related_tag_id`, `risk_domain_l1`, `risk_type_l2`, `platform`, `core_keywords`, `related_corpus_count`, `total_interaction`, `avg_risk_score`, `case_priority_score`, `representative_corpus_id`, `representative_text`, `spread_mechanism`, `disposal_strategy_platform`, `disposal_strategy_6_12`, `disposal_strategy_13_15`, `disposal_strategy_16_18`, `convertible_script_type`, `review_status`, `related_script_id`, `risk_level`, `incident_time`, `source_url`, `spread_path`, `interaction_feature`, `review_conclusion`, `created_at`, `updated_at`) VALUES ('L1-001','罗昌平侮辱 “冰雕连” 英烈案',NULL,'历史认知风险','英烈亵渎 / 娱乐化','微博',NULL,0,0,0.00,0.00,NULL,'2021年10月6日9时38分，罗昌平使用其新浪微博账号（粉丝约220万）在观看电影《长津湖》及长津湖战役纪录片后，发布帖文戏谑、侮辱在长津湖战役中牺牲的中国人民志愿军“冰雕连”英烈，称“‘冰雕连’是‘装’的”等不当内容，帖文阅读量超2.2万，引发公众强烈愤慨。','贴文阅读量超2.2万 | 引发公众强烈愤慨','依法追究法律责任（刑事/行政/公益诉讼）；平台立即下架违规内容、永久封禁账号；公开道歉、消除影响；平台建立英烈关键词拦截与人工复核机制','1.以英雄故事、动画、绘本、榜样示范为主要形式，强化英烈形象的崇高性与神圣感。\n2.明确告知：英雄烈士是民族的守护者，不可以开玩笑、不可以恶搞、不可以编成段子。\n3.结合升旗仪式、纪念日活动，建立直观情感认同，让孩子从内心产生尊敬与爱戴。\n4.引导识别网络恶搞视频，知道这类内容是不对、不尊重、伤害民族情感的。','1.开展英雄烈士保护法治教育，讲解侮辱英烈的法律后果与道德危害。\n2.引导辨析 “娱乐玩梗” 与 “历史亵渎” 的边界，识别历史虚无主义的隐蔽话术。\n3.组织观看纪实影像、亲历者口述，还原真实历史场景，破除 “不合理、不科学” 等造谣式质疑。\n4.强化底线意识：爱国从尊重英雄开始，不跟风、不转发、不参与恶搞。','1.从民族精神、国家认同、意识形态安全三层理解英烈保护的意义。\n2.深度剖析娱乐化、解构化、段子化背后的历史虚无主义逻辑，看清其削弱历史认知的目的。\n3.开展批判性讨论：为何有人刻意抹黑英雄？如何用史料与逻辑反驳历史虚无观点？\n4.强化责任意识：自觉成为历史守护者，主动抵制错误言论，维护历史真相。',NULL,0,NULL,'L3','2021-10-06','https://www.spp.gov.cn/spp/zdgz/202205/t20220505_556174.shtml','用户微博发布','引发公众强烈愤慨','英烈亵渎类内容常以“玩梗”“二次创作”为包装，在短视频、社交媒体中隐蔽传播，易削弱青少年对历史的敬畏心。需坚持“零容忍”态度，法律打击与正面宣传并重，同时强化青少年英烈事迹教育，从源头增强历史认同。','2026-06-08 13:05:40','2026-06-09 21:52:13'),('L1-002','“作业本” 调侃邱少云烈士案',NULL,'历史认知风险','英烈亵渎 / 娱乐化','微博',NULL,0,0,0.00,0.00,NULL,'微博用户 “作业本”（孙杰） 公开发文，将邱少云烈士在火中牺牲的事迹恶意改编为 “烧烤” 段子，并用低俗语言侮辱烈士','热度较高 | 引发公众强烈愤慨','依法追究法律责任（刑事/行政/公益诉讼）；平台立即下架违规内容、永久封禁账号；公开道歉、消除影响；平台建立英烈关键词拦截与人工复核机制','1.以英雄故事、动画、绘本、榜样示范为主要形式，强化英烈形象的崇高性与神圣感。\n2.明确告知：英雄烈士是民族的守护者，不可以开玩笑、不可以恶搞、不可以编成段子。\n3.结合升旗仪式、纪念日活动，建立直观情感认同，让孩子从内心产生尊敬与爱戴。\n5.引导识别网络恶搞视频，知道这类内容是不对、不尊重、伤害民族情感的。','1.开展英雄烈士保护法治教育，讲解侮辱英烈的法律后果与道德危害。\n2.引导辨析 “娱乐玩梗” 与 “历史亵渎” 的边界，识别历史虚无主义的隐蔽话术。\n3.组织观看纪实影像、亲历者口述，还原真实历史场景，破除 “不合理、不科学” 等造谣式质疑。\n5.强化底线意识：爱国从尊重英雄开始，不跟风、不转发、不参与恶搞。','1.从民族精神、国家认同、意识形态安全三层理解英烈保护的意义。\n2.深度剖析娱乐化、解构化、段子化背后的历史虚无主义逻辑，看清其削弱历史认知的目的。\n3.开展批判性讨论：为何有人刻意抹黑英雄？如何用史料与逻辑反驳历史虚无观点？\n5.强化责任意识：自觉成为历史守护者，主动抵制错误言论，维护历史真相。',NULL,0,NULL,'L4','2016-09-02','https://www.xinhuanet.com/food/old_2014/specials/special/food2016/2/zt/index.htm','用户在加多宝微博下评论','引发公众强烈愤慨','英烈亵渎类内容常以“玩梗”“二次创作”为包装，在短视频、社交媒体中隐蔽传播，易削弱青少年对历史的敬畏心。需坚持“零容忍”态度，法律打击与正面宣传并重，同时强化青少年英烈事迹教育，从源头增强历史认同。','2026-06-08 13:05:40','2026-06-09 21:52:12'),('L1-003','网民侮辱陈尔晋、王曼霞烈士案',NULL,'历史认知风险','英烈亵渎 / 娱乐化','短视频平台',NULL,0,0,0.00,0.00,NULL,'2023年5月至6月，网民张某为博取流量，在某短视频平台发布两条使用“加入不明武装”（实指加入中国共产党）、“美人计”“枪毙”等误导性、贬损性词语的视频，丑化中共地下党员、革命烈士陈尔晋（1911–1949）与王曼霞（？–1949）夫妇。','两视频播放量分别超1万次和9000次，引发上百条恶意评论 | 造成恶劣社会影响','依法追究法律责任（刑事/行政/公益诉讼）；平台立即下架违规内容、永久封禁账号；公开道歉、消除影响；平台建立英烈关键词拦截与人工复核机制','1.以英雄故事、动画、绘本、榜样示范为主要形式，强化英烈形象的崇高性与神圣感。\n2.明确告知：英雄烈士是民族的守护者，不可以开玩笑、不可以恶搞、不可以编成段子。\n3.结合升旗仪式、纪念日活动，建立直观情感认同，让孩子从内心产生尊敬与爱戴。\n6.引导识别网络恶搞视频，知道这类内容是不对、不尊重、伤害民族情感的。','1.开展英雄烈士保护法治教育，讲解侮辱英烈的法律后果与道德危害。\n2.引导辨析 “娱乐玩梗” 与 “历史亵渎” 的边界，识别历史虚无主义的隐蔽话术。\n3.组织观看纪实影像、亲历者口述，还原真实历史场景，破除 “不合理、不科学” 等造谣式质疑。\n6.强化底线意识：爱国从尊重英雄开始，不跟风、不转发、不参与恶搞。','1.从民族精神、国家认同、意识形态安全三层理解英烈保护的意义。\n2.深度剖析娱乐化、解构化、段子化背后的历史虚无主义逻辑，看清其削弱历史认知的目的。\n3.开展批判性讨论：为何有人刻意抹黑英雄？如何用史料与逻辑反驳历史虚无观点？\n6.强化责任意识：自觉成为历史守护者，主动抵制错误言论，维护历史真相。',NULL,0,NULL,'L3',NULL,'https://tyjrsw.yn.gov.cn/c/2026-05-08/7134275.shtml','用户在某短视频平台发布视频','造成恶劣社会影响','英烈亵渎类内容常以“玩梗”“二次创作”为包装，在短视频、社交媒体中隐蔽传播，易削弱青少年对历史的敬畏心。需坚持“零容忍”态度，法律打击与正面宣传并重，同时强化青少年英烈事迹教育，从源头增强历史认同。','2026-06-08 13:05:40','2026-06-09 21:52:13'),('L2-001','吹捧蒋介石、捏造“共军只毙敌851人”',NULL,'历史认知风险','近现代史虚无化、旧时代美化和反向叙事','微博',NULL,0,0,0.00,0.00,NULL,'近年来，网络舆论场持续出现一股“翻案史学”潮流。某些自媒体在蒋介石逝世纪念日、抗战胜利日等节点，通过捏造数据、断章取义等手段吹捧蒋介石“日记抗日”，夸大国民党军队作用。典型言论包括捏造“共军只击毙851名日军”的荒诞数据，并声称“国民党牺牲206位将领，共产党仅牺牲左权1位”。',NULL,'依法删除不实信息，对恶意造谣者行政处罚；平台对“翻案史学”“民国美化”等内容限流、下架、封禁；联合网信部门开展历史类内容专项治理；组织权威历史学者发布辟谣与正本清源内容','1.以正向历史叙事、图片对比、生活变迁故事为主，建立 “国家越来越好、生活越来越幸福” 的直观认知。\n2.观看适合儿童的主旋律动画与短片，了解新中国的建立与发展来之不易。\n3.不接触碎片化、片面化、美化旧时代的不良内容，建立朴素家国情感。','1.提供史料、数据、纪实材料，纠正 “民国黄金时代”“今不如昔” 等片面叙事。\n2.学会区分片段事实与完整历史，不被剪辑影像、幸存者偏差误导。\n3.了解不同历史阶段的发展背景，理解社会进步的连续性与艰巨性。\n4.引导全面客观看历史，不盲从自媒体片面结论。','1.从历史规律、发展阶段、国际比较、结构性因素理性辨析历史虚无主义陷阱。\n2.深度识别反向叙事、片面归因、选择性呈现的话语套路。\n3.理解历史虚无主义对道路认同、制度认同的侵蚀作用，增强辨别能力。\n4.树立正确历史观：尊重历史、尊重事实、尊重奋斗历程。',NULL,0,NULL,'L4',NULL,'https://mp.weixin.qq.com/s?__biz=MjM5MjAxNDM4MA==&mid=220519663&idx=1&sn=c298078c4633896a4ee572600196a309&chksm=2e7cb5ac190b3cba82e1069829942c106a1b12b041b597bcd2522af2adce43acc2985932f01c&scene=27','微博文章','','历史虚无主义常以“选择性呈现”“数据造假”“碎片化传播”为手法，将复杂历史简化为二元对立。需用权威史料、对比数据、百姓获得感故事进行系统性反击，同时培养青少年历史思辨能力，识破“翻案史学”的话术陷阱。','2026-06-08 13:05:40','2026-06-09 21:37:27'),('L2-002','邓某杰贬低中共抗战地位案',NULL,'历史认知风险','近现代史虚无化、旧时代美化和反向叙事','社交平台',NULL,0,0,0.00,0.00,NULL,'网民邓某杰于 2025 年 4 月 28 日在社交平台编造 “中共军队歼灭日军仅 851 人” 的虚假数据，刻意贬低中国共产党在抗战中的中流砥柱作用','造成恶劣社会影响','依法删除不实信息，对恶意造谣者行政处罚；平台对“翻案史学”“民国美化”等内容限流、下架、封禁；联合网信部门开展历史类内容专项治理；组织权威历史学者发布辟谣与正本清源内容','1.以正向历史叙事、图片对比、生活变迁故事为主，建立 “国家越来越好、生活越来越幸福” 的直观认知。\n2.观看适合儿童的主旋律动画与短片，了解新中国的建立与发展来之不易。\n4.不接触碎片化、片面化、美化旧时代的不良内容，建立朴素家国情感。','1.提供史料、数据、纪实材料，纠正 “民国黄金时代”“今不如昔” 等片面叙事。\n2.学会区分片段事实与完整历史，不被剪辑影像、幸存者偏差误导。\n3.了解不同历史阶段的发展背景，理解社会进步的连续性与艰巨性。\n5.引导全面客观看历史，不盲从自媒体片面结论。','1.从历史规律、发展阶段、国际比较、结构性因素理性辨析历史虚无主义陷阱。\n2.深度识别反向叙事、片面归因、选择性呈现的话语套路。\n3.理解历史虚无主义对道路认同、制度认同的侵蚀作用，增强辨别能力。\n5.树立正确历史观：尊重历史、尊重事实、尊重奋斗历程。',NULL,0,NULL,'L3','2025-04-02','https://www.bjwmb.gov.cn/wmpl/10099576.html','社交平台上发表不实言论','造成恶劣社会影响','历史虚无主义常以“选择性呈现”“数据造假”“碎片化传播”为手法，将复杂历史简化为二元对立。需用权威史料、对比数据、百姓获得感故事进行系统性反击，同时培养青少年历史思辨能力，识破“翻案史学”的话术陷阱。','2026-06-08 13:05:40','2026-06-09 21:52:13'),('L2-003','“民国黄金时代” 美化叙事案',NULL,'历史认知风险','近现代史虚无化、旧时代美化和反向叙事','抖音',NULL,0,0,0.00,0.00,NULL,'大量短视频账号剪辑民国富人生活、服饰、街景，配文 “民国浪漫”“黄金时代”，隐瞒饥荒、战乱、文盲率高等历史事实','点赞2.3万，评论145，收藏2222，转发1938','依法删除不实信息，对恶意造谣者行政处罚；平台对“翻案史学”“民国美化”等内容限流、下架、封禁；联合网信部门开展历史类内容专项治理；组织权威历史学者发布辟谣与正本清源内容','1.以正向历史叙事、图片对比、生活变迁故事为主，建立 “国家越来越好、生活越来越幸福” 的直观认知。\n2.观看适合儿童的主旋律动画与短片，了解新中国的建立与发展来之不易。\n5.不接触碎片化、片面化、美化旧时代的不良内容，建立朴素家国情感。','1.提供史料、数据、纪实材料，纠正 “民国黄金时代”“今不如昔” 等片面叙事。\n2.学会区分片段事实与完整历史，不被剪辑影像、幸存者偏差误导。\n3.了解不同历史阶段的发展背景，理解社会进步的连续性与艰巨性。\n6.引导全面客观看历史，不盲从自媒体片面结论。','1.从历史规律、发展阶段、国际比较、结构性因素理性辨析历史虚无主义陷阱。\n2.深度识别反向叙事、片面归因、选择性呈现的话语套路。\n3.理解历史虚无主义对道路认同、制度认同的侵蚀作用，增强辨别能力。\n6.树立正确历史观：尊重历史、尊重事实、尊重奋斗历程。',NULL,0,NULL,'L3','2022-08-02','5.38 复制打开抖音，看看【武痴甲元霍的作品】1935年民国时期，富二代吃午餐珍贵影像，不仅有管... https://v.douyin.com/LREbaVnzZ9g/ gOk:/ 08/02 G@V.Lj :1pm','抖音视频','','历史虚无主义常以“选择性呈现”“数据造假”“碎片化传播”为手法，将复杂历史简化为二元对立。需用权威史料、对比数据、百姓获得感故事进行系统性反击，同时培养青少年历史思辨能力，识破“翻案史学”的话术陷阱。','2026-06-08 13:05:40','2026-06-09 21:52:12'),('L3-001','薛某撕扯焚烧国旗案',NULL,'历史认知风险','国家符号亵渎和轻慢化使用','个人微信朋友圈及境外社交软件',NULL,0,0,0.00,0.00,NULL,'薛某在地铁站公然撕扯、踩踏、焚烧中华人民共和国国旗，并拍摄视频发布到社交平台炫耀，视频快速传播','造成恶劣社会影响','依法追究刑事/行政责任；平台建立国旗、国徽、国歌、党旗、军旗、人民币等关键词拦截机制；制定《国家符号网络使用规范》行业标准；对直播、短视频、文创等重点领域进行专项整顿','1.开展国旗、国歌、国徽基本知识与礼仪教育，培养仪式感与庄重态度。\n2.明确国家象征代表国家尊严，必须严肃、认真、敬重。\n3.在升旗、集会等场合规范言行，不嬉闹、不喧哗，从小养成敬畏习惯。','1.学习国旗法、国歌法、国徽法等法律常识，明确娱乐化、恶搞属于不当行为。\n2.识别鬼畜、恶搞、变调、低俗改编等危害，不观看、不传播、不模仿。\n3.理解国家符号与民族情感、国家尊严紧密相关，强化公民责任感。','1.从国家尊严、公民义务、法治底线、意识形态安全理解符号保护意义。\n2.看清轻慢化、娱乐化、戏谑化对国家认同的侵蚀作用。\n3.自觉维护国家象征庄重性，主动抵制不良创作与违规使用。\n4.以法治思维与公民意识规范自身网络行为。',NULL,0,NULL,'L4',NULL,'https://fx.lncourt.gov.cn/article/detail/2023/09/id/7544426.shtml','用随身携带的手机将上述过程拍照、录制视频，发布至个人微信朋友圈及境外社交软件','造成恶劣社会影响','国家符号亵渎呈现娱乐化、商业化、碎片化趋势，尤以直播、短视频、表情包为高发场景。需法律、平台治理、宣传教育三管齐下，从“不敢”到“不想”，逐步形成全社会自觉尊重的氛围。','2026-06-08 13:05:40','2026-06-09 21:52:13'),('L3-002','网红用国歌配乐低俗舞蹈案',NULL,'历史认知风险','国家符号亵渎和轻慢化使用','虎牙直播',NULL,0,0,0.00,0.00,NULL,'虎牙主播莉哥在直播中，公然篡改国歌曲谱，以嬉皮笑脸的方式表现国歌内容，并将国歌作为自己所谓“网络音乐会”的“开幕曲”','造成恶劣社会影响','依法追究刑事/行政责任；平台建立国旗、国徽、国歌、党旗、军旗、人民币等关键词拦截机制；制定《国家符号网络使用规范》行业标准；对直播、短视频、文创等重点领域进行专项整顿','1.开展国旗、国歌、国徽基本知识与礼仪教育，培养仪式感与庄重态度。\n2.明确国家象征代表国家尊严，必须严肃、认真、敬重。\n4.在升旗、集会等场合规范言行，不嬉闹、不喧哗，从小养成敬畏习惯。','1.学习国旗法、国歌法、国徽法等法律常识，明确娱乐化、恶搞属于不当行为。\n2.识别鬼畜、恶搞、变调、低俗改编等危害，不观看、不传播、不模仿。\n4.理解国家符号与民族情感、国家尊严紧密相关，强化公民责任感。','1.从国家尊严、公民义务、法治底线、意识形态安全理解符号保护意义。\n2.看清轻慢化、娱乐化、戏谑化对国家认同的侵蚀作用。\n3.自觉维护国家象征庄重性，主动抵制不良创作与违规使用。\n5.以法治思维与公民意识规范自身网络行为。',NULL,0,NULL,'L3',NULL,'https://weibo.com/ttarticle/p/show?id=2309404293524651673417','虎牙直播过程中','造成恶劣社会影响','国家符号亵渎呈现娱乐化、商业化、碎片化趋势，尤以直播、短视频、表情包为高发场景。需法律、平台治理、宣传教育三管齐下，从“不敢”到“不想”，逐步形成全社会自觉尊重的氛围。','2026-06-08 13:05:40','2026-06-09 21:52:13'),('POS-H01','公安机关网安部门依法查处6起侮辱英烈案',NULL,'历史认知风险','英烈亵渎 / 娱乐化',NULL,'英烈亵渎 / 娱乐化、历史认知风险、中青网正向案例',0,0,0.00,0.00,NULL,'中青网跟踪报道公安机关依法查处侮辱英烈内容，体现平台与执法机关协同治理网络乱象的正向路径。',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'https://t.m.youth.cn/transfer/index/url/news.youth.cn/gn/202507/t20250707_16102673.htm',NULL,NULL,NULL,'2026-07-03 11:55:21','2026-07-03 11:55:21'),('POS-H02','罗昌平侵害英雄烈士名誉、荣誉暨刑事附带民事公益诉讼一案一审宣判',NULL,'历史认知风险','英烈亵渎 / 娱乐化',NULL,'英烈亵渎 / 娱乐化、历史认知风险、中青网正向案例',0,0,0.00,0.00,NULL,'中青网关注该案司法宣判结果，展示法律对亵渎英烈行为的刚性约束，是历史认知类议题的权威处置参考。',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'https://m.youth.cn/qwtx/xxl/202205/t20220505_13668597.htm',NULL,NULL,NULL,'2026-07-03 11:55:21','2026-07-03 11:55:21'),('POS-H03','琉球跨越百年的苦难与抗争：民族的伤口与未竟的正义',NULL,'历史认知风险','近现代史虚无化、旧时代美化和反向叙事',NULL,'近现代史虚无化、旧时代美化和反向叙事、历史认知风险、中青网正向案例',0,0,0.00,0.00,NULL,'中青网系统梳理琉球百年殖民历史，以权威史料对冲境外反向叙事，是历史认知风险议题的正向叙事范本。',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'https://news.youth.cn/gj/202606/t20260623_16726996.htm',NULL,NULL,NULL,'2026-07-03 11:55:21','2026-07-03 11:55:21'),('POS-H04','双面《戏台》：老祖宗与旧时代',NULL,'历史认知风险','近现代史虚无化、旧时代美化和反向叙事',NULL,'近现代史虚无化、旧时代美化和反向叙事、历史认知风险、中青网正向案例',0,0,0.00,0.00,NULL,'中青网文艺评论理性辨析影视作品对旧时代的美化倾向，引导受众用完整史料看待近现代历史。',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'https://fun.youth.cn/gnzx/202508/t20250806_16159741.htm',NULL,NULL,NULL,'2026-07-03 11:55:21','2026-07-03 11:55:21'),('POS-H05','篡改戏唱国歌的主播不能仅止于凉凉',NULL,'历史认知风险','国家符号亵渎和轻慢化使用',NULL,'国家符号亵渎和轻慢化使用、历史认知风险、中青网正向案例',0,0,0.00,0.00,NULL,'中青网评论批评主播戏唱国歌行为，呼吁社会严肃对待国家符号，是国家符号类议题的权威表态。',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'https://pinglun.youth.cn/ttst/201810/t20181011_11751644.htm',NULL,NULL,NULL,'2026-07-03 11:55:21','2026-07-03 11:55:21'),('POS-H06','把“旭日旗”当日本国旗，错了就是错了',NULL,'历史认知风险','国家符号亵渎和轻慢化使用',NULL,'国家符号亵渎和轻慢化使用、历史认知风险、中青网正向案例',0,0,0.00,0.00,NULL,'中青网评论纠正旭日旗与日本国旗混淆的错误认知，示范如何理性辨析历史符号争议。',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'https://pinglun.youth.cn/wztt/202011/t20201121_12585039.htm',NULL,NULL,NULL,'2026-07-03 11:55:21','2026-07-03 11:55:21'),('POS-H07','宣传栏里国旗四颗小星星平行排列',NULL,'历史认知风险','国家符号亵渎和轻慢化使用',NULL,'国家符号亵渎和轻慢化使用、历史认知风险、中青网正向案例',0,0,0.00,0.00,NULL,'中青网报道推动纠正公共场所错版国旗问题，体现媒体监督对国家符号规范使用的正向作用。',NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,'https://news.youth.cn/sh/201608/t20160829_8603124.htm',NULL,NULL,NULL,'2026-07-03 11:55:21','2026-07-03 11:55:21'),('R1-002','成都 1 死 11 伤',NULL,'认知闭合风险','阴谋论和身份对立叙事以“万能解释”满足认知闭合需求','微博',NULL,0,0,0.00,0.00,NULL,'成都发生致 1 死 11 伤的意外事件后，部分网民不采信官方通报与事实调查结论，在短视频、评论区、群组内大肆传播阴谋论叙事：将事件定性为 “报复社会”“故意杀人”“掩盖真相”，并把伤亡、现场、动机等一切疑点统一解释为 **“官方压热度、删帖封口、背后有黑幕、势力操控”；同时构建身份对立 **，把 “相信通报” 的人打成 “洗地、5 毛、被洗脑”，把 “信阴谋” 的人奉为 “清醒、敢说真话”，用一套万能阴谋解释封闭所有理性讨论。',NULL,'快速发布官方通报，压缩阴谋论传播窗口；对典型阴谋论账号依法处置；建立“事实核查”专区与辟谣平台；推送科学思维、逻辑推理、媒介素养教育内容','1.相信家长、老师、官方通报等正规信息。\n2.不听 “吓人秘密、黑幕、压热度” 等奇怪说法，不害怕、不盲从。\n4.养成 “有疑问问大人” 的习惯。','1.学会看证据、查来源、辨真假，不信没有根据的阴谋论。\n2.识别 “官方掩盖、被洗脑、洗地” 等标签化对立话术。\n4.不盲目站队、不参与对立、不被情绪煽动。','1.识别认知闭环、身份对立、阴谋话术的完整逻辑与心理机制。\n2.坚持多元视角、事实核查、理性判断，拒绝极端封闭认知。\n4.看清阴谋论制造对立、破坏信任、扰乱社会心态的现实危害。',NULL,0,NULL,'L3','2026-05-01','https://weibo.com/6545306636/5293948853289800','微博发表言论','','阴谋论以确定性满足认知闭合需求，突发事件是其高发窗口。需“快速发声+透明调查+情绪疏导+素养教育”四管齐下，长期目标是从“满足确定性需求”转向“培养对不确定性的健康容忍度”。','2026-06-08 13:05:40','2026-06-09 21:52:12'),('R1-003','癸酉本石头记',NULL,'认知闭合风险','阴谋论和身份对立叙事以“万能解释”满足认知闭合需求','微博',NULL,0,0,0.00,0.00,NULL,'网络上围绕《癸酉本石头记》（被称为 “鬼本”）形成极端圈层：支持者无视学界版本考据、文本年代、语言风格、物证缺失等大量疑点，坚信癸酉本是《红楼梦》“唯一真本”，将通行本、红学研究、专家考证均斥为 **“被篡改、被删减、掩盖真相”；面对学界质疑与事实破绽，统一用“学界打压、资本垄断、利益集团封口、官方掩盖真相”等万能阴谋论回应，并构建身份对立 **：信癸酉本 =“看透真相”，信通行本 / 信专家 =“被蒙蔽、被规训”。',NULL,'快速发布官方通报，压缩阴谋论传播窗口；对典型阴谋论账号依法处置；建立“事实核查”专区与辟谣平台；推送科学思维、逻辑推理、媒介素养教育内容','1.相信家长、老师、官方通报等正规信息。\n2.不听 “吓人秘密、黑幕、压热度” 等奇怪说法，不害怕、不盲从。\n5.养成 “有疑问问大人” 的习惯。','1.学会看证据、查来源、辨真假，不信没有根据的阴谋论。\n2.识别 “官方掩盖、被洗脑、洗地” 等标签化对立话术。\n5.不盲目站队、不参与对立、不被情绪煽动。','1.识别认知闭环、身份对立、阴谋话术的完整逻辑与心理机制。\n2.坚持多元视角、事实核查、理性判断，拒绝极端封闭认知。\n5.看清阴谋论制造对立、破坏信任、扰乱社会心态的现实危害。',NULL,0,NULL,'L3',NULL,'https://weibo.com/2460937233/5242685112716257','微博讨论','','阴谋论以确定性满足认知闭合需求，突发事件是其高发窗口。需“快速发声+透明调查+情绪疏导+素养教育”四管齐下，长期目标是从“满足确定性需求”转向“培养对不确定性的健康容忍度”。','2026-06-08 13:05:40','2026-06-09 21:52:13'),('R2-001','赖清德窜访斯威士兰',NULL,'认知闭合风险','极端民族主义以“绝对正确”替代复杂理解','微博',NULL,0,0,0.00,0.00,NULL,'赖清德窜访斯威士兰事件引发舆论关注，部分网民以极端民族主义情绪进行绝对化、口号式宣泄，将事件简单定性为 “台独挑衅、外部势力围堵、小国背叛”，完全无视斯威士兰的外交立场、小国生存策略、台海外交格局、中非多边关系、两岸长期博弈等复杂背景。相关内容将理性分析、外交常识、多角度解读一概扣上 “卖国、洗地” 帽子，以 “强硬反制才是爱国” 为唯一正确答案，压制理性讨论空间。',NULL,'对极端宣泄、血统论、历史绝对化内容限流或下架；推送理性国际关系、历史多元解读、民族团结科普；对煽动民族对立者依法处置','1.培养爱国情感、礼貌友善、团结包容的态度。\n2.不骂人、不排斥、不极端，友好对待他人。','1.引导理性爱国，不狭隘、不极端、不非黑即白。\n2.不使用攻击性语言，不跟风谩骂，不盲目排外。\n3.理解爱国需要理性、自信、包容。','1.树立大国心态、开放包容、理性平和的民族情感。\n2.反对狭隘民族主义、极端对立与情绪暴力。\n3.用理性与格局看待国际事务与多元观点。',NULL,0,NULL,'L3','2026-05-06','https://weibo.com/1699432410/5295603517229685','微博评论区','','极端民族主义以“绝对正确”压制多元理解，易导致认知狭隘与对外偏激。需用“专业知识+多元视角+共情教育”进行平衡，同时区分“理性爱国”与“极端排外”，引导青少年形成开放、自信、理性的民族观。','2026-06-08 13:05:40','2026-06-09 21:52:13'),('R2-002','纯种汉人',NULL,'认知闭合风险','极端民族主义以“绝对正确”替代复杂理解','微博',NULL,0,0,0.00,0.00,NULL,'网络上出现宣扬 “纯种汉人” 血统至上、族群纯洁论的极端言论，刻意无视中国几千年各民族迁徙、通婚、融合的基本史实，否定中华民族多元一体格局，编造 “汉人血统纯正、高贵正统” 等错误观点，将历史上的民族融合歪曲为 “血统污染”，将文化认同替换为血统认同。相关内容以 “汉人正统” 为绝对正确，排斥多民族共生、文化互鉴、多元一体的复杂现实，宣扬狭隘族群优越论。','点赞超200 | 言语激进极端','对极端宣泄、血统论、历史绝对化内容限流或下架；推送理性国际关系、历史多元解读、民族团结科普；对煽动民族对立者依法处置','1.培养爱国情感、礼貌友善、团结包容的态度。\n3.不骂人、不排斥、不极端，友好对待他人。','1.引导理性爱国，不狭隘、不极端、不非黑即白。\n2.不使用攻击性语言，不跟风谩骂，不盲目排外。\n4.理解爱国需要理性、自信、包容。','1.树立大国心态、开放包容、理性平和的民族情感。\n2.反对狭隘民族主义、极端对立与情绪暴力。\n4.用理性与格局看待国际事务与多元观点。',NULL,0,NULL,'L2',NULL,'https://weibo.com/1749277070/5086227017239964','微博发表言论后视频','言语激进极端','极端民族主义以“绝对正确”压制多元理解，易导致认知狭隘与对外偏激。需用“专业知识+多元视角+共情教育”进行平衡，同时区分“理性爱国”与“极端排外”，引导青少年形成开放、自信、理性的民族观。','2026-06-08 13:05:40','2026-06-08 13:05:40'),('R2-003','澎湖海战',NULL,'认知闭合风险','极端民族主义以“绝对正确”替代复杂理解','微博',NULL,0,0,0.00,0.00,NULL,'网络舆论将清朝与郑氏政权之间的澎湖海战简化为 “中华民族统一正义之战”，以极端民族主义立场进行绝对化解读，片面突出 “统一即正义、抵抗即叛逆” 的单一结论，完全无视战争爆发的历史背景、明清易代政权性质、东南沿海势力格局、军事冲突的多重动因、两岸关系历史复杂性等内容。相关内容拒绝历史多面性，将战役简化为民族立场之争，以 “统一绝对正确” 封闭一切多元解释。',NULL,'对极端宣泄、血统论、历史绝对化内容限流或下架；推送理性国际关系、历史多元解读、民族团结科普；对煽动民族对立者依法处置','1.培养爱国情感、礼貌友善、团结包容的态度。\n4.不骂人、不排斥、不极端，友好对待他人。','1.引导理性爱国，不狭隘、不极端、不非黑即白。\n2.不使用攻击性语言，不跟风谩骂，不盲目排外。\n5.理解爱国需要理性、自信、包容。','1.树立大国心态、开放包容、理性平和的民族情感。\n2.反对狭隘民族主义、极端对立与情绪暴力。\n5.用理性与格局看待国际事务与多元观点。',NULL,0,NULL,'L2','2026-05-02','http://s.weibo.com/weibo?q=%E6%BE%8E%E6%B9%96%E6%B5%B7%E6%88%98','微博话题讨论','','极端民族主义以“绝对正确”压制多元理解，易导致认知狭隘与对外偏激。需用“专业知识+多元视角+共情教育”进行平衡，同时区分“理性爱国”与“极端排外”，引导青少年形成开放、自信、理性的民族观。','2026-06-08 13:05:40','2026-06-08 13:05:40'),('R3-001','“中医无效” 言论案',NULL,'认知闭合风险','本土文化贬低，西方文化崇拜','抖音',NULL,0,0,0.00,0.00,NULL,'期贬低中医药 “不科学、骗人、落后”，鼓吹全盘西医','点赞101，评论183','下架此类贬低内容；推送传统文化现代价值解读与创新案例；对西方刻板印象内容进行批判引导','1.接触传统节日、传统故事、国风艺术，建立文化亲切感。\n2.喜欢并尊重本土文化，不盲目觉得 “外国的更好”。','1.认识各文化各有所长，不贬低自己、不崇拜西方。\n2.识别审美殖民、文化自卑的隐蔽表现。\n3.增强文化自尊与文化自信。','1.建立文化自觉、文化自信、文明平等对话意识。\n2.理性看待西方审美霸权与文化输出逻辑。\n3.自觉传承本土文化，尊重文明多样性。',NULL,0,NULL,'L2','2026-01-09','8.46 复制打开抖音，看看【孤勇者的图文作品】不跟信中医的人玩，没脑子。  https://v.douyin.com/Jn7YgmmrqyQ/ V@L.WM 01/21 ndn:/ :4pm','发表图文','','复盘结论	本土文化贬低常与西方审美霸权、消费主义捆绑，易使青少年产生文化自卑。需用“创造性转化、创新性发展”的案例与叙事，从“文化自觉”走向“文化自信”，同时揭露西方刻板印象背后的殖民逻辑。','2026-06-08 13:05:40','2026-06-08 13:05:40'),('R3-002','迪奥 “丑化亚裔” 摄影案',NULL,'认知闭合风险','本土文化贬低，西方文化崇拜','小红书',NULL,0,0,0.00,0.00,NULL,'迪奥发布摄影作品，用眯眯眼、病态肤色等刻板印象塑造亚裔形象，强化西方审美霸权','点赞、评论超100','下架此类贬低内容；推送传统文化现代价值解读与创新案例；对西方刻板印象内容进行批判引导','1.接触传统节日、传统故事、国风艺术，建立文化亲切感。\n3.喜欢并尊重本土文化，不盲目觉得 “外国的更好”。','1.认识各文化各有所长，不贬低自己、不崇拜西方。\n2.识别审美殖民、文化自卑的隐蔽表现。\n4.增强文化自尊与文化自信。','1.建立文化自觉、文化自信、文明平等对话意识。\n2.理性看待西方审美霸权与文化输出逻辑。\n4.自觉传承本土文化，尊重文明多样性。',NULL,0,NULL,'L2',NULL,'https://m.thepaper.cn/baijiahao_15428316','在小红书发表图文','','复盘结论	本土文化贬低常与西方审美霸权、消费主义捆绑，易使青少年产生文化自卑。需用“创造性转化、创新性发展”的案例与叙事，从“文化自觉”走向“文化自信”，同时揭露西方刻板印象背后的殖民逻辑。','2026-06-08 13:05:40','2026-06-08 13:05:40'),('R3-003','“汉服糟粕” 笔记案',NULL,'认知闭合风险','本土文化贬低，西方文化崇拜','小红书',NULL,0,0,0.00,0.00,NULL,'小红书某博主发文称 “汉服宽袍大袖、不方便、是封建糟粕，不如